import { CommonModule } from '@angular/common';
import { Component, inject, signal, viewChild } from '@angular/core';
import { FormBuilder, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import {
  IonBackButton,
  IonButton,
  IonButtons,
  IonContent,
  IonHeader,
  IonIcon,
  IonItem,
  IonLabel,
  IonList,
  IonMenuToggle,
  IonSearchbar,
  IonTitle,
  IonToolbar,
  ViewWillEnter,
} from '@ionic/angular/standalone';
import { addIcons } from 'ionicons';
import { closeCircle, searchOutline } from 'ionicons/icons';
import {
  BehaviorSubject,
  combineLatest,
  firstValueFrom,
  from,
  map,
  shareReplay,
  startWith,
  switchMap,
} from 'rxjs';
import { getAllBooks } from 'supabase/functions/_shared/book';
import { titleCase } from 'title-case';
import {
  favoritesRoutePath,
  getFavoritesRoutePath,
  getRoutePath,
  searchRoutePath,
  verseRoutePath,
} from '../app.routes';
import { MenuToggleComponent } from '../common/menu/menu-toggle.component';
import { ResultsComponent } from '../common/results/results.component';
import { TagChipComponent } from '../common/tag-chip/tag-chip.component';
import { TimerService } from '../common/timer/timer.service';
import { SkeletonCardComponent } from '../common/verse/skeleton-card/skeleton-card.component';
import { Tag, Verse } from '../common/verse/verse';
import { parseBibleReference } from '../search/parse';
import { EmptyComponent } from './empty/empty.component';
import { FavoritesService } from './favorites.service';

const BIBLE_BOOKS = getAllBooks();

@Component({
  selector: 'app-favorites',
  templateUrl: './favorites.page.html',
  styleUrls: ['./favorites.page.scss'],
  imports: [
    IonButton,
    IonButtons,
    IonContent,
    IonHeader,
    IonIcon,
    IonItem,
    IonLabel,
    IonList,
    IonMenuToggle,
    IonSearchbar,
    IonTitle,
    IonToolbar,
    CommonModule,
    ReactiveFormsModule,
    EmptyComponent,
    ResultsComponent,
    SkeletonCardComponent,
    RouterModule,
    MenuToggleComponent,
    IonBackButton,
    TagChipComponent,
  ],
})
export class FavoritesPage implements ViewWillEnter {
  private favoritesService = inject(FavoritesService);
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private timerService = inject(TimerService);

  readonly searchRouterLink = [getRoutePath(searchRoutePath)];
  readonly versesRoute = getFavoritesRoutePath(verseRoutePath);

  searchbar = viewChild<IonSearchbar>('searchbar');

  showSuggestions = signal(false);
  private readonly availableTags$ = new BehaviorSubject<Tag[]>([]);

  private readonly refresh$ = new BehaviorSubject<void>(undefined);

  formGroup = inject(FormBuilder).group({
    query: [''],
  });

  // Current filters state - kept in sync with route params
  private currentFilters$ = new BehaviorSubject<{ tagIds: number[]; books: string[]; verses: string[] }>({
    tagIds: [],
    books: [],
    verses: [],
  });

  // Subscribe to route params and update currentFilters$
  private filters$ = this.route.queryParams.pipe(
    map((params) => ({
      tagIds: this.parseNumberArray(params['tagIds']),
      books: this.parseStringArray(params['books']),
      verses: this.parseStringArray(params['verses']),
    })),
    shareReplay(1)
  );

  constructor() {
    addIcons({ searchOutline, closeCircle });
    // Keep currentFilters$ in sync with route params
    this.filters$.subscribe((filters) => this.currentFilters$.next(filters));
  }

  // Derived state for template use
  selectedTagIds$ = this.currentFilters$.pipe(map((f) => new Set(f.tagIds)));
  selectedBooks$ = this.currentFilters$.pipe(map((f) => f.books));
  selectedVerseSearches$ = this.currentFilters$.pipe(map((f) => f.verses));
  hasActiveFilters$ = this.currentFilters$.pipe(
    map((f) => f.tagIds.length > 0 || f.books.length > 0 || f.verses.length > 0)
  );
  selectedTags$ = combineLatest([this.currentFilters$, this.availableTags$]).pipe(
    map(([filters, tags]) => tags.filter((tag) => filters.tagIds.includes(tag.id)))
  );

  // Combined suggestions for books, tags, and verse searches
  suggestions$ = combineLatest([
    this.formGroup.controls.query.valueChanges.pipe(startWith('')),
    this.currentFilters$,
    this.availableTags$,
  ]).pipe(
    map(([query, filters, availableTags]) => {
      const suggestions: {
        type: 'book' | 'tag' | 'verse';
        value: string;
        id?: number;
        color?: string;
      }[] = [];

      if (!query) {
        return suggestions;
      }

      const lowerCaseQuery = query.toLowerCase();
      const trimmedQuery = query.trim();

      // Check if it's a verse search (has chapter:verse pattern)
      const versePattern = /^(.+?)\s+(\d+):(\d+)/;
      const verseMatch = trimmedQuery.match(versePattern);

      if (verseMatch) {
        // It's a verse search - add it as a suggestion
        suggestions.push({
          type: 'verse',
          value: trimmedQuery,
        });
        return suggestions;
      }

      // If it includes ':' or ends with a number, don't show book/tag suggestions
      if (query.includes(':') || /\d/.test(query.split(' ').pop() || '')) {
        return suggestions;
      }

      // Add matching books (filter out already selected ones)
      const matchingBooks = BIBLE_BOOKS.filter(
        (book) =>
          book.toLowerCase().startsWith(lowerCaseQuery) &&
          !filters.books.includes(titleCase(book))
      ).map((book) => ({
        type: 'book' as const,
        value: titleCase(book),
      }));
      suggestions.push(...matchingBooks);

      // Add matching tags (filter out already selected ones)
      const selectedTagIds = new Set(filters.tagIds);
      const matchingTags = availableTags
        .filter(
          (tag) =>
            tag.name.toLowerCase().startsWith(lowerCaseQuery) &&
            !selectedTagIds.has(tag.id)
        )
        .map((tag) => ({
          type: 'tag' as const,
          value: tag.name,
          id: tag.id,
          color: tag.color || '#6366f1',
        }));
      suggestions.push(...matchingTags);

      return suggestions;
    }),
    shareReplay(1)
  );

  allFavorites$ = this.refresh$.pipe(
    switchMap(() => from(this.favoritesService.getFavorites())),
    shareReplay(1)
  );

  filteredFavorites$ = combineLatest([
    this.allFavorites$,
    this.currentFilters$,
  ]).pipe(
    map(([favorites, filters]) => {
      const { tagIds, books, verses } = filters;

      // If no filters are active, return all favorites
      const hasFilters =
        tagIds.length > 0 || books.length > 0 || verses.length > 0;

      if (!hasFilters) {
        return favorites;
      }

      // Collect matching verse IDs from each filter type (OR logic across all types)
      const matchingVerseIds = new Set<number>();

      // Add verses matching selected tags
      if (tagIds.length > 0) {
        const selectedTagSet = new Set(tagIds);
        favorites.forEach((verse) => {
          const verseTagIds = new Set(verse.tags?.map((t) => t.id) ?? []);
          for (const tagId of selectedTagSet) {
            if (verseTagIds.has(tagId)) {
              matchingVerseIds.add(verse.id!);
              break;
            }
          }
        });
      }

      // Add verses matching selected books
      if (books.length > 0) {
        favorites.forEach((verse) => {
          const verseBook = (verse.book || '').toLowerCase();
          if (books.some((book) => book.toLowerCase() === verseBook)) {
            matchingVerseIds.add(verse.id!);
          }
        });
      }

      // Add verses matching selected verse searches
      if (verses.length > 0) {
        verses.forEach((verseSearch) => {
          const normalizedQuery = verseSearch.trim().replace(/\s+/g, ' ');
          const parsed = parseBibleReference(normalizedQuery);

          if (parsed && !isNaN(parsed.chapter)) {
            const matchingVerses = this.filterFavorites(favorites, parsed);
            matchingVerses.forEach((verse) => {
              matchingVerseIds.add(verse.id!);
            });
          }
        });
      }

      // Return all verses that match any criteria
      return favorites.filter((verse) => matchingVerseIds.has(verse.id!));
    }),
    shareReplay(1)
  );

  async ionViewWillEnter() {
    this.refresh$.next();
    await this.loadTags();
  }

  onFavoriteRemoved() {
    this.refresh$.next();
  }

  async onTagsChanged() {
    this.refresh$.next();
    await this.loadTags();
  }

  private async loadTags() {
    const tags = await this.favoritesService.getUserTags();
    this.availableTags$.next(tags);
  }

  private parseNumberArray(value: string | undefined): number[] {
    if (!value) return [];
    return value
      .split(',')
      .map((s) => parseInt(s.trim(), 10))
      .filter((n) => !isNaN(n));
  }

  private parseStringArray(value: string | undefined): string[] {
    if (!value) return [];
    return value.split(',').map((s) => s.trim()).filter(Boolean);
  }

  private navigateWithFilters(filters: {
    tagIds?: number[];
    books?: string[];
    verses?: string[];
  }) {
    const currentFilters = {
      ...this.currentFilters$.getValue(),
      ...filters,
    };

    // Update local state immediately for rapid successive operations
    this.currentFilters$.next(currentFilters);

    const queryParams: Record<string, string> = {};
    if (currentFilters.tagIds.length > 0) {
      queryParams['tagIds'] = currentFilters.tagIds.join(',');
    }
    if (currentFilters.books.length > 0) {
      queryParams['books'] = currentFilters.books.join(',');
    }
    if (currentFilters.verses.length > 0) {
      queryParams['verses'] = currentFilters.verses.join(',');
    }

    this.router.navigate([getRoutePath(favoritesRoutePath)], { queryParams });
  }

  private filterFavorites(
    favorites: Verse[],
    parsed: { book: string; chapter: number; verses: number[] | 'ALL' }
  ): Verse[] {
    return favorites.filter((favorite) => {
      // Filter by book
      const favoriteBook = (favorite.book || '').toLowerCase();
      const parsedBook = parsed.book.toLowerCase();
      if (favoriteBook !== parsedBook) {
        return false;
      }

      // Filter by chapter
      if (favorite.chapter !== parsed.chapter) {
        return false;
      }

      // Filter by verse(s)
      if (parsed.verses !== 'ALL' && parsed.verses.length > 0) {
        const startVerse = favorite.start_verse ?? 0;
        const endVerse = favorite.end_verse ?? startVerse;

        // Check if any of the searched verses is within the range of start_verse and end_verse
        const hasMatchingVerse = parsed.verses.some(
          (verse) => verse >= startVerse && verse <= endVerse
        );

        if (!hasMatchingVerse) {
          return false;
        }
      }

      return true;
    });
  }

  handleInput(event: any) {
    const query = event.target.value || '';
    this.formGroup.controls.query.setValue(query, { emitEvent: true });
    this.showSuggestions.set(true);
  }

  handleKeyDown(event: KeyboardEvent) {
    if (event.key === 'Enter') {
      event.preventDefault();
      this.handleSearchSubmit();
    }
  }

  selectBook(book: string) {
    const current = this.currentFilters$.getValue().books;
    if (!current.includes(book)) {
      this.navigateWithFilters({ books: [...current, book] });
    }
    this.formGroup.controls.query.setValue('', { emitEvent: true });
    this.showSuggestions.set(false);
  }

  selectTag(tagId: number) {
    const current = this.currentFilters$.getValue().tagIds;
    if (!current.includes(tagId)) {
      this.navigateWithFilters({ tagIds: [...current, tagId] });
    }
    this.formGroup.controls.query.setValue('', { emitEvent: true });
    this.showSuggestions.set(false);
  }

  selectVerseSearch(verseSearch: string) {
    const current = this.currentFilters$.getValue().verses;
    if (!current.includes(verseSearch)) {
      this.navigateWithFilters({ verses: [...current, verseSearch] });
    }
    this.formGroup.controls.query.setValue('', { emitEvent: true });
    this.showSuggestions.set(false);
  }

  removeBook(book: string) {
    const current = this.currentFilters$.getValue().books;
    this.navigateWithFilters({ books: current.filter((b) => b !== book) });
  }

  removeTag(tagId: number) {
    const current = this.currentFilters$.getValue().tagIds;
    this.navigateWithFilters({ tagIds: current.filter((id) => id !== tagId) });
  }

  removeVerseSearch(verseSearch: string) {
    const current = this.currentFilters$.getValue().verses;
    this.navigateWithFilters({ verses: current.filter((v) => v !== verseSearch) });
  }

  handleSearchSubmit() {
    const query = this.formGroup.controls.query.value?.trim() || '';
    if (query) {
      const versePattern = /^(.+?)\s+(\d+):(\d+)/;
      if (versePattern.test(query)) {
        this.selectVerseSearch(query);
      }
    }
  }

  async hideSuggestionsWithDelay() {
    await firstValueFrom(this.timerService.timer(150));
    this.showSuggestions.set(false);
  }

  clearFilters() {
    this.formGroup.patchValue({ query: '' });
    this.currentFilters$.next({ tagIds: [], books: [], verses: [] });
    this.router.navigate([getRoutePath(favoritesRoutePath)]);
  }
}
